const KEY='renal-picture-quiz-v1', PREF_KEY='renal-picture-quiz-preferences-v1', $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let bank,bankVersion,manifest,coverage={lectures:{}},p=empty(),screen='home',zoom=1,original=false,settings=defaultSettings();
let byId={};const root=$('#app');let timer;
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(timer);timer=setTimeout(()=>$('#toast').style.display='none',4500);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(p));}catch{toast('Progress could not be saved. Export it before leaving.');}}
