function download(name,value){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),500);}
function option(value,text,current){return `<option value="${esc(value)}" ${value===current?'selected':''}>${esc(text)}</option>`;}
function resetZoom(){zoom=1;original=false;}
function coverageMarkup(){const lectures=[...new Set(bank.map(q=>q.collection))];return `<section class="coverage-section"><div class="row spread"><div><p class="eyebrow">Know what is covered</p><h2>Lecture coverage</h2></div><span class="fine">Coverage is not a mastery score</span></div><div class="grid">${lectures.map(id=>{const qs=bank.filter(q=>q.collection===id),info=coverage.lectures?.[id],sources=manifest.sources.filter(s=>s.lecture_id===id);return `<article class="card coverage-card"><div class="row spread"><h3>${esc(id)}</h3><span class="tag">${esc(info?.status||'Coverage not yet audited')}</span></div><p class="fine">${qs.length} questions · ${new Set(qs.map(q=>q.source_group_id)).size} scored visual ${new Set(qs.map(q=>q.source_group_id)).size===1?'source':'sources'} · ${sources.filter(s=>s.status!=='USABLE').length} reference or repeated captures</p><details><summary>Tested topics and remaining gaps</summary><h4>Tested in this bank</h4><ul>${(info?.tested_summary||[...new Set(qs.map(q=>q.tested_concept))]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h4>Still missing or incomplete</h4>${info?`<ul>${info.gaps.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p class="fine">${esc(info.next_capture)}</p>`:'<p class="fine">No lecture-wide coverage audit is recorded yet. Question count alone does not establish completeness.</p>'}<p class="fine">${esc(info?.basis||'Tested concepts are derived from the current scored question bank.')}</p></details></article>`;}).join('')}</div></section>`;}
function home(){screen='home';const pool=filtered(bank,p,settings),available=bank.length,seen=bank.filter(q=>p.groups[q.source_group_id]?.times_seen).length,missed=filtered(bank,p,{filter:'incorrect'}).length,lectures=[...new Set(bank.map(q=>q.collection))],count=sessionSize(pool.length,settings.length);
 root.innerHTML=`<section class="hero"><div class="intro"><p class="eyebrow">Renal · Visual practice</p><h1>Look closely.<br>Learn what matters.</h1><p class="muted">Practice renal anatomy, physiology, and hemodynamics using your manual lecture captures. Every question starts with the image.</p><div class="stats"><div class="card stat"><strong>${available}</strong><span>Verified questions</span></div><div class="card stat"><strong>${new Set(bank.map(q=>q.source_group_id)).size}</strong><span>Visual groups</span></div><div class="card stat"><strong>${missed}</strong><span>To revisit</span></div></div><span class="tag">${seen} / ${available} questions from seen sources</span><p class="fine mt">Manual captures from ${lectures.slice(0,-1).join(', ')}, and ${lectures.at(-1)} are represented, but lecture coverage remains partial. Related questions share source history.</p></div><div class="card practice-panel"><p class="eyebrow">Make this session yours</p><h2>Choose your practice</h2><fieldset class="box-group"><legend>Mode</legend><div class="mode-boxes">${[['learn','Learn','Feedback after each answer'],['exam','Exam','Feedback at the end']].map(([value,title,description])=>`<label class="select-box"><input type="radio" name="mode" value="${value}" aria-label="${title}" ${settings.mode===value?'checked':''}><span class="box-face"><strong>${title}</strong><small>${description}</small></span></label>`).join('')}</div></fieldset><fieldset class="box-group"><legend>Session length</legend><div class="length-boxes">${[['10','10','10 questions'],['20','20','20 questions'],['40','40','40 questions'],['all','All available','All available'],['endless','Endless','Endless practice']].map(([value,title,label])=>`<label class="select-box ${value==='all'||value==='endless'?'wide':''}"><input type="radio" name="length" value="${value}" aria-label="${label}" ${settings.length===value?'checked':''}><span class="box-face"><strong>${title}</strong></span></label>`).join('')}</div></fieldset><fieldset class="box-group lecture-picker"><legend>Lectures</legend><div class="lecture-boxes">${lectures.map(id=>`<label class="select-box"><input type="checkbox" name="lecture" value="${esc(id)}" aria-label="${esc(id)}" ${settings.collection==='all'||settings.collection.includes(id)?'checked':''}><span class="box-face"><strong>${esc(id)}</strong><small>${bank.filter(q=>q.collection===id).length} questions</small></span></label>`).join('')}</div><button id="all-lectures" class="quiet">Select all lectures</button></fieldset><div class="form-grid"><div><label for="category">Image category</label><select id="category">${option('all','All image types',settings.category)}${[...new Set(bank.map(q=>q.category))].map(x=>option(x,`${x} (${filtered(bank,p,{category:x,collection:settings.collection}).length})`,settings.category)).join('')}</select></div><div><label for="filter">Question selection</label><select id="filter">${[['all','Mixed practice'],['unseen','Unseen sources'],['incorrect','Previously incorrect'],['marked','Marked for review']].map(([v,t])=>option(v,`${t} (${filtered(bank,p,{...settings,filter:v}).length})`,settings.filter)).join('')}</select></div></div><p class="fine mt session-availability">${pool.length?`${pool.length} available · ${settings.length==='endless'?'Repeats the selected pool':`${count} in this session`}`:'No questions match. Select a lecture or change your filters.'}</p><button id="start" class="primary full" ${!pool.length?'disabled':''}>${settings.length==='endless'?`Start endless · ${count} questions`:`Start ${count} ${count===1?'question':'questions'}`}</button>${p.session&&!p.session.complete?'<button id="resume" class="full mt">Resume saved session</button>':''}<p class="fine mt no-margin">Progress stays in this browser. No account or network connection is needed for local use.</p></div></section><div class="notice">Your originals are preserved. Unsafe or repetitive captures stay in Source review rather than entering scored sessions. Additional manual captures can extend lecture coverage later.</div>${coverageMarkup()}`;
 for(const id of ['category','filter'])$('#'+id).onchange=e=>{settings[id]=e.target.value;saveSettings();home();$('#'+id).focus({preventScroll:true});};
 document.querySelectorAll('.select-box input[type=radio]').forEach(el=>el.onchange=()=>{const {name,value}=el;settings[name]=value;saveSettings();home();document.querySelector(`input[name="${name}"][value="${value}"]`).focus({preventScroll:true});});
 document.querySelectorAll('input[name=lecture]').forEach((el,index)=>el.onchange=()=>{const chosen=new Set(settings.collection==='all'?lectures:settings.collection);el.checked?chosen.add(el.value):chosen.delete(el.value);settings.collection=[...chosen];saveSettings();home();document.querySelectorAll('input[name=lecture]')[index].focus({preventScroll:true});});
 bind('all-lectures',()=>{settings.collection='all';saveSettings();home();$('#all-lectures').focus({preventScroll:true});});
 bind('start',()=>{if(p.session&&!p.session.complete&&!confirm('Start a new session? Your scored progress is kept, but the unfinished session will be replaced.'))return;p.session=session(pool,settings.mode,settings.length);save();resetZoom();quiz();window.scrollTo(0,0);});bind('resume',()=>{resetZoom();quiz();window.scrollTo(0,0);});
}
function imageMarkup(q,reveal){return `<div class="visual"><div class="image-frame" id="frame"><img id="quiz-image" src="${esc(q.image)}" alt="Quiz source image" decoding="async" fetchpriority="high"></div><div class="image-toolbar"><div class="row"><button id="zoom-out" aria-label="Zoom out">−</button><button id="zoom-in" aria-label="Zoom in">+</button><button id="fit">Fit image</button></div><span class="fine" id="zoom-label">100%</span></div><div class="image-toolbar">${reveal?'<button id="original">Show teaching original</button>':'<span class="fine">Quiz image only</span>'}<button id="fullscreen">Full image</button></div></div>`;}
function applyZoom(q){const frame=$('#frame'),img=$('#quiz-image');if(!frame||!img)return;frame.classList.toggle('zoomed',zoom>1);frame.style.setProperty('--zoom-width',`${frame.clientWidth*zoom}px`);img.src=original?q.original_image:zoom>1?q.zoom_image:q.image;$('#zoom-label').textContent=`${Math.round(zoom*100)}%`;if(zoom===1){frame.scrollTop=0;frame.scrollLeft=0;}if($('#original'))$('#original').textContent=original?'Show quiz image':'Show teaching original';}
function wireImage(q,reveal){bind('zoom-in',()=>{zoom=Math.min(4,zoom+.5);applyZoom(q);});bind('zoom-out',()=>{zoom=Math.max(1,zoom-.5);applyZoom(q);});bind('fit',()=>{zoom=1;applyZoom(q);});if(reveal){bind('original',()=>{original=!original;applyZoom(q);});}bind('fullscreen',()=>{const d=document.createElement('dialog');d.className='full-image-viewer';d.innerHTML=`<div class="row spread"><h3 class="no-margin">Full image</h3><button id="close-dialog">Close</button></div><div class="row full-image-tools"><button id="full-out" aria-label="Zoom full image out">−</button><button id="full-in" aria-label="Zoom full image in">+</button><button id="full-fit">Fit image</button><span class="fine" id="full-scale">100%</span></div><div class="image-frame full-image-frame" id="full-frame"><img src="${esc(reveal&&original?q.original_image:q.zoom_image)}" alt="${reveal&&original?'Teaching original':'Quiz source image'}"></div>`;document.body.append(d);d.showModal();let scale=1,drag=null;const frame=d.querySelector('#full-frame');const apply=()=>{frame.classList.toggle('zoomed',scale>1);frame.style.setProperty('--zoom-width',`${frame.clientWidth*scale}px`);d.querySelector('#full-scale').textContent=`${Math.round(scale*100)}%`;if(scale===1){frame.scrollTop=0;frame.scrollLeft=0;}};d.querySelector('#close-dialog').onclick=()=>d.close();d.querySelector('#full-in').onclick=()=>{scale=Math.min(4,scale+.5);apply();};d.querySelector('#full-out').onclick=()=>{scale=Math.max(1,scale-.5);apply();};d.querySelector('#full-fit').onclick=()=>{scale=1;apply();};frame.onpointerdown=e=>{if(scale===1)return;drag={x:e.clientX,y:e.clientY,left:frame.scrollLeft,top:frame.scrollTop};frame.setPointerCapture(e.pointerId);};frame.onpointermove=e=>{if(drag){frame.scrollLeft=drag.left-e.clientX+drag.x;frame.scrollTop=drag.top-e.clientY+drag.y;}};frame.onpointerup=()=>drag=null;frame.onpointercancel=()=>drag=null;d.onclose=()=>d.remove();});
 const frame=$('#frame');let drag=null;frame.onpointerdown=e=>{if(zoom===1)return;drag={x:e.clientX,y:e.clientY,left:frame.scrollLeft,top:frame.scrollTop};frame.setPointerCapture(e.pointerId);};frame.onpointermove=e=>{if(drag){frame.scrollLeft=drag.left-e.clientX+drag.x;frame.scrollTop=drag.top-e.clientY+drag.y;}};frame.onpointerup=()=>drag=null;frame.onpointercancel=()=>drag=null;applyZoom(q);}
function feedback(q,it){const result=!it.locked?'Unanswered':it.overridden?'Corrected with Keanne Button':it.correct?'Correct':'Not quite';return `<section class="feedback" id="feedback"><p class="result ${it.overridden?'override-text':it.locked&&!it.correct?'wrong-text':''}">${result}</p><p>${esc(q.explanation)}</p><h3>What to notice</h3><ul>${q.visual_clues.map(c=>`<li>${esc(c)}</li>`).join('')}</ul><h3>Every option explained</h3>${it.order.map(k=>`<div class="rationale"><strong>${k===q.correct_index?'✓ Correct answer · ':''}${k===it.draft?'Your choice · ':''}${esc(q.options[k])}</strong><p>${esc(q.choice_rationales[k])}</p></div>`).join('')}<p class="citation mt">${q.citations.map(c=>c.page==null?esc(c.document):`${esc(c.document)}, p. ${c.page}`).join('<br>')}</p><details><summary>Image provenance</summary><p class="citation">${esc(q.original_filename)}<br>${esc(q.source_id)}<br>Lecture capture · ${esc(q.collection)}</p></details>${it.locked&&!it.correct?'<button id="keanne">Keanne Button</button><p class="fine">Count this locked answer as correct without changing your selected option or adding an attempt.</p>':''}</section>`;}
const mobileLayout=window.matchMedia('(max-width:850px)');
function positionQuestion(){const heading=$('#question-heading');if(!heading)return;if(mobileLayout.matches)document.querySelector('.quiz-layout').prepend(heading);else document.querySelector('.question').prepend(heading);}
mobileLayout.addEventListener('change',positionQuestion);
function quiz(){screen='quiz';const s=p.session;if(!s?.items.length)return home();const it=s.items[s.index],q=byId[it.id];if(!q)return home();see(p,q,it);save();const reveal=canReveal(s,it);root.innerHTML=`<div class="quiz-meta"><span>${s.complete?'Session review':s.mode==='learn'?'Learn mode':'Exam mode'} · ${esc(q.collection)}</span><span>${s.index+1} / ${s.items.length} ${s.endless?'· Endless':''}</span><progress max="${s.items.length}" value="${s.index+1}"></progress><button id="finish" class="quiet">${s.complete?'Back to results':'Finish session'}</button></div><section class="quiz-layout">${imageMarkup(q,reveal)}<div class="card question"><div class="question-heading" id="question-heading"><p class="eyebrow">${esc(q.category)} · Visual practical</p><h2>${esc(q.stem)}</h2></div><div class="choices">${it.order.map((k,pos)=>`<button class="choice ${it.draft===k?'selected':''} ${reveal&&k===q.correct_index?'correct':''} ${reveal&&it.draft===k&&!it.correct?'wrong':''} ${reveal&&it.draft===k&&it.overridden?'overridden':''}" data-choice="${k}" ${it.locked||s.complete?'disabled':''}><span class="letter">${pos+1}</span>${esc(q.options[k])}</button>`).join('')}</div><div class="controls"><button id="back" ${s.index===0?'disabled':''}>Back</button><button id="submit" class="primary" ${it.draft===null||it.locked||s.complete?'disabled':''}>${it.locked?'Answer locked':'Submit answer'}</button><button id="next">${s.index===s.items.length-1&&!s.endless?'Finish':'Next'}</button></div><div class="row mt"><button id="mark" class="quiet">${p.questions[q.question_id]?.marked?'★ Marked':'☆ Mark for review'}</button><button id="flag" class="quiet">${p.flags[q.question_id]?.status==='open'?'Image flagged':'Flag image'}</button></div><p class="fine">1–4 to choose · Enter to submit or advance · Z to zoom<br>You can skip and return without losing a draft.</p>${!reveal&&it.locked?'<p class="notice">Answer saved. Feedback appears after the exam.</p>':''}${reveal?feedback(q,it):''}</div></section>`;
 document.querySelectorAll('[data-choice]').forEach(el=>el.onclick=()=>{it.draft=Number(el.dataset.choice);save();quiz();});
 bind('submit',()=>{if(answer(p,q,it)){save();quiz();}});bind('back',()=>move(-1));bind('next',()=>move(1));bind('finish',()=>{if(s.complete)results();else if(confirm('Finish this session? Unanswered questions will be reported separately.'))finish();});
 bind('mark',()=>{const st=p.questions[q.question_id];st.marked=!st.marked;save();quiz();});
 bind('flag',()=>{const note=prompt('What needs attention in this image?',p.flags[q.question_id]?.note||'');if(note===null)return;p.flags[q.question_id]={question_id:q.question_id,source_id:q.source_id,variant_id:q.variant_id,status:'open',note,date:new Date().toISOString()};save();quiz();toast('Image flagged for review.');});
 bind('keanne',()=>{if(override(p,q,it)){if(s.complete&&Number.isInteger(s.result_index))p.exams[s.result_index]={...p.exams[s.result_index],...totals(s)};save();quiz();}});positionQuestion();wireImage(q,reveal);
}
function move(delta){const s=p.session;if(s.index+delta<0)return;if(s.index+delta>=s.items.length){if(s.endless&&!s.complete){const prior=byId[s.items.at(-1).id].source_group_id;s.items.push(...ordered(bank.filter(q=>s.pool.includes(q.question_id)),Math.random,prior).map(q=>item(q)));}else{return s.complete?results():finish();}}s.index+=delta;resetZoom();save();quiz();window.scrollTo(0,0);}
function finish(){const s=p.session;if(!s.complete){s.complete=true;s.result_index=p.exams.length;p.exams.push({date:new Date().toISOString(),mode:s.mode,...totals(s)});save();}results();}
function results(){screen='results';const s=p.session,t=totals(s);const breakdown={};s.items.forEach(it=>{const q=byId[it.id];const key=q.category;let b=breakdown[key]??={correct:0,answered:0};if(it.locked){b.answered++;if(it.correct)b.correct++;}});root.innerHTML=`<section class="summary"><p class="eyebrow">Session complete</p><h1>A closer look,<br>a stronger memory.</h1><p class="muted">${t.total-t.unanswered?((t.correct/(t.total-t.unanswered))*100).toFixed(2):'0.00'}% of answered questions correct. Unanswered questions are not scored.</p><div class="stats"><div class="card stat"><strong>${t.correct}</strong><span>Correct</span></div><div class="card stat"><strong>${t.incorrect}</strong><span>Incorrect</span></div><div class="card stat"><strong>${t.unanswered}</strong><span>Unanswered</span></div></div><div class="card"><h2>Review your session</h2><p class="fine">${Object.entries(breakdown).map(([k,v])=>`${esc(k)} ${v.correct}/${v.answered} answered`).join(' · ')}</p><div class="row"><button id="retry" ${!t.incorrect?'disabled':''}>Retry missed questions</button><button id="again" class="primary">New practice</button></div><div class="mt">${s.items.map((it,i)=>`<p class="row spread"><span>${i+1}. ${esc(byId[it.id].tested_concept)}${p.questions[it.id]?.marked?' ★':''}</span><button data-review="${i}" class="quiet">${!it.locked?'Unanswered':it.overridden?'Corrected':it.correct?'Correct':'Incorrect'} · Review</button></p>`).join('')}</div></div></section>`;
 document.querySelectorAll('[data-review]').forEach(el=>el.onclick=()=>{s.index=Number(el.dataset.review);resetZoom();quiz();});bind('again',home);bind('retry',()=>{const ids=new Set(s.items.filter(i=>i.locked&&!i.correct).map(i=>i.id));p.session=session(bank.filter(q=>ids.has(q.question_id)),'learn','all');save();resetZoom();quiz();});}
function progress(){screen='progress';const stats=Object.values(p.questions),n=stats.reduce((a,s)=>a+s.times_answered,0),c=stats.reduce((a,s)=>a+s.correct_count,0);root.innerHTML=`<section class="summary"><p class="eyebrow">Your local record</p><h1>Keep your progress.</h1><p class="muted">${n} answered attempts · ${n?(100*c/n).toFixed(2):'0.00'}% correct. Browser data does not automatically sync between devices or site addresses.</p><div class="card"><div class="row"><button id="export">Export progress</button><label class="file-label">Import progress<input id="import" type="file" accept=".json,application/json"></label><button id="reset">Reset progress</button></div><p class="fine mt">Export before changing browsers, moving to a hosted URL, or clearing browser storage. Import replaces this browser’s progress only after confirmation.</p><h3>Concept practice</h3>${Object.entries(p.concepts).map(([k,v])=>`<p class="fine">${esc(k)} · ${v.correct} correct / ${v.correct+v.incorrect} answered</p>`).join('')||'<p class="fine">Your first session will appear here.</p>'}</div></section>`;
 bind('export',()=>download('renal-progress.json',p));bind('reset',()=>{if(confirm('Reset all local progress, sessions, flags, and review decisions? Source images and questions will not change.')){p=empty();save();progress();}});$('#import').onchange=async e=>{try{let f=e.target.files[0];if(!f)return;if(f.size>5e6)throw Error('File is too large.');let incoming=validateImport(JSON.parse(await f.text()),bank);if(confirm('Replace this browser’s progress with this export?')){p=incoming;save();progress();toast('Progress imported.');}}catch(e){toast(e.message);}};
}
function review(){screen='review';const flags=Object.values(p.flags);root.innerHTML=`<p class="eyebrow">Reviewer workspace · Answers visible</p><h1>Sources, not shortcuts.</h1><p class="muted">${manifest.sources.length} manual captures reviewed. ${new Set(bank.map(q=>q.source_group_id)).size} distinct visual source groups support scored tasks. ${manifest.sources.filter(s=>s.status!=='USABLE').length} remain teaching references or alternate annotated views.</p><div class="row"><button id="export-flags">Export flags & decisions</button><button id="open-flags">${flags.filter(f=>f.status==='open').length} open image flags</button></div><div class="card mt"><h3>Learner image flags</h3>${flags.length?flags.map(f=>`<div class="rationale"><p>${esc(byId[f.question_id]?.tested_concept||f.question_id)} · ${esc(f.status)}</p><p>${esc(f.note)}</p><button data-flag="${esc(f.question_id)}">${f.status==='open'?'Mark resolved':'Reopen flag'}</button></div>`).join(''):'<p class="fine">No image flags yet. Use Flag image during a quiz to record a problem.</p>'}</div><div class="grid mt">${manifest.sources.map(s=>`<article class="card review-item"><span class="tag">${esc(s.status)}</span><h3 class="mt">${esc(s.tested_concept)}</h3><img class="review-img" src="${esc(s.original_asset)}" alt="Teaching original for source review" loading="lazy" decoding="async"><p>${esc(s.review_reason)}</p><details><summary>Source and full image</summary><a href="${esc(s.original_asset)}" target="_blank" rel="noopener">Open original at full size</a><p>${esc(s.relative_path)}<br>${esc(s.source_citation.document)}, p. ${s.source_citation.page}</p><p>${esc(s.source_id)}</p></details><label for="note-${s.source_id}">Review note or proposed correction</label><textarea id="note-${s.source_id}">${esc(p.decisions[s.source_id]?.note||'')}</textarea><div class="pill-actions mt">${['retain','crop','exclude','needs_review'].map(a=>`<button data-decision="${esc(s.source_id)}" data-action="${a}" data-n="${s.source_id}">${a.replace('_',' ')}</button>`).join('')}</div><p class="fine" id="decision-${s.source_id}">${esc(p.decisions[s.source_id]?.action||'No local decision')}</p></article>`).join('')}</div><p class="notice mt">Review decisions are saved locally and exportable. They do not silently alter the scored bank. Approved corrections need a rebuilt and validated bank before activation.</p>`;
 bind('export-flags',()=>download('renal-image-review.json',{schema_version:1,bank_version:bankVersion,flags:p.flags,decisions:p.decisions}));bind('open-flags',()=>document.querySelector('.card.mt').scrollIntoView());document.querySelectorAll('[data-flag]').forEach(el=>el.onclick=()=>{const f=p.flags[el.dataset.flag];f.status=f.status==='open'?'resolved':'open';f.date=new Date().toISOString();save();review();});document.querySelectorAll('[data-decision]').forEach(el=>el.onclick=()=>{p.decisions[el.dataset.decision]={action:el.dataset.action,note:$('#note-'+el.dataset.n).value,date:new Date().toISOString()};save();$('#decision-'+el.dataset.n).textContent='Saved · '+el.dataset.action;toast('Review decision saved locally.');});
}
document.addEventListener('keydown',e=>{if(screen!=='quiz'||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||document.querySelector('dialog[open]'))return;if(['1','2','3','4'].includes(e.key)){const b=document.querySelectorAll('[data-choice]')[Number(e.key)-1];if(b&&!b.disabled)b.click();}else if(e.key==='Enter'){e.preventDefault();const b=$('#submit');if(b&&!b.disabled)b.click();else $('#next')?.click();}else if(e.key.toLowerCase()==='z'){$('#zoom-in')?.click();}});
try{const [b,m,c]=await Promise.all([fetch('./data/question-bank.json?v=20261005r3').then(r=>{if(!r.ok)throw Error('Question bank is missing.');return r.json();}),fetch('./data/source-manifest.json?v=20261005r3').then(r=>r.json()),fetch('./data/coverage.json?v=20261005r3').then(r=>r.ok?r.json():{lectures:{}}).catch(()=>({lectures:{}}))]);bank=b.questions;bankVersion=b.bank_version;manifest=m;coverage=c;try{const saved=JSON.parse(localStorage.getItem(PREF_KEY)||'null');if(saved?.schema_version===1)settings=normalizeSettings(saved,bank);}catch{toast('Saved menu preferences could not be loaded.');}byId=Object.fromEntries(bank.map(q=>[q.question_id,q]));try{const raw=localStorage.getItem(KEY);if(raw)p=validateImport(JSON.parse(raw),bank);}catch{toast('Saved data could not be loaded. It has not been erased.');}bind('home',()=>{home();window.scrollTo(0,0);});bind('review',()=>{review();window.scrollTo(0,0);});bind('progress',()=>{progress();window.scrollTo(0,0);});home();}catch(e){root.innerHTML=`<div class="notice warning"><h2>The quiz could not load</h2><p>${esc(e.message)}</p><p>Use Start Quiz.command or serve this folder locally. Do not open index.html directly with a file URL.</p></div>`;}
